/**
 * PPE (furniture, equipment, ...) layer for the Sherubtse College webmap.
 *
 * Data comes from the PPE Excel sheet:
 *   - when the map is opened through the server (npm start), it is read live
 *     from /api/assets and refreshed automatically;
 *   - when index.html is opened as a plain file, it uses inventory_data.js
 *     (regenerated by the server / scripts/build_inventory.js).
 *
 * Each building with records gets a count marker. Clicking a building shows
 * all its records (grouped by Custodian/Room) in the side panel.
 * map URL ?building=<name> opens that building directly.
 */
(function () {
  'use strict';
  if (typeof map === 'undefined' || !window.INVENTORY_DATA) {
    console.warn('PPE layer: map or INVENTORY_DATA missing');
    return;
  }
  var DATA = window.INVENTORY_DATA;
  // Backend: Google Apps Script (google.script.run) or the Node server (/api/assets).
  var GAS = typeof google !== 'undefined' && google.script && google.script.run;
  var LIVE = GAS || /^https?:$/.test(location.protocol);
  var ADMIN_URL = GAS ? (window.PPE_BASE_URL || '') + '?page=admin' : '/admin/';
  var adminLink = function (building) {
    return ADMIN_URL + (building ? (ADMIN_URL.indexOf('?') >= 0 ? '&' : '?') + 'building=' + encodeURIComponent(building) : '');
  };
  var SOURCE = GAS ? 'Google Sheet' : 'Excel';
  var CAT_COLORS = { Furniture: '#b5651d', Equipment: '#0f7c8c', Vehicle: '#7048e8', Building: '#5c7cfa', Land: '#2b8a3e' };
  var catColor = function (c) { return CAT_COLORS[c] || '#868e96'; };

  var places = {};
  DATA.places.forEach(function (p) { places[p.key] = p; });
  var fmt = new ol.format.GeoJSON();
  var toMap = { dataProjection: 'EPSG:4326', featureProjection: map.getView().getProjection() };
  var state = { q: '', cat: 'All', cond: 'All', selected: null };

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { return n == null || isNaN(n) ? '' : Number(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function groupBy(arr, fn) {
    var out = {};
    arr.forEach(function (x) { var k = fn(x); (out[k] = out[k] || []).push(x); });
    return out;
  }
  var sumQty = function (arr) { return arr.reduce(function (s, it) { return s + (Number(it.qty) || 0); }, 0); };
  var sumCost = function (arr) { return arr.reduce(function (s, it) { return s + (it.cost != null ? Number(it.cost) * (Number(it.qty) || 1) : 0); }, 0); };

  function filtered() {
    var q = state.q.toLowerCase();
    return DATA.items.filter(function (it) {
      if (state.cat !== 'All' && (it.category || 'Other') !== state.cat) return false;
      if (state.cond !== 'All' && (it.condition || 'Unknown') !== state.cond) return false;
      if (!q) return true;
      return [it.description, it.code, it.building, it.room, it.category, it.remarks].join(' ').toLowerCase().indexOf(q) >= 0;
    });
  }

  // ---------------------------------------------------------------- layers
  var markerSource = new ol.source.Vector();
  var styleCache = {};
  function badgeStyle(feature) {
    var n = feature.get('count'), sel = feature.get('building') === state.selected;
    var key = n + '|' + sel;
    if (!styleCache[key]) {
      styleCache[key] = new ol.style.Style({
        image: new ol.style.Circle({
          radius: Math.min(10 + Math.log10(n + 1) * 6, 24),
          fill: new ol.style.Fill({ color: sel ? '#d9480f' : '#1d3557' }),
          stroke: new ol.style.Stroke({ color: '#ffffff', width: 2 }),
        }),
        text: new ol.style.Text({
          text: String(n), font: 'bold 11px "Segoe UI", Arial, sans-serif',
          fill: new ol.style.Fill({ color: '#ffffff' }),
        }),
        zIndex: sel ? 2 : 1,
      });
    }
    return styleCache[key];
  }
  var markerLayer = new ol.layer.Vector({
    title: 'Furniture & Equipment (PPE)',
    source: markerSource,
    style: badgeStyle,
    zIndex: 1000,
    interactive: false, // keep the stock qgis2web popup away from these markers
  });
  var highlightSource = new ol.source.Vector();
  map.addLayer(new ol.layer.Vector({
    source: highlightSource, zIndex: 999, interactive: false,
    style: new ol.style.Style({
      stroke: new ol.style.Stroke({ color: '#ff7b00', width: 3 }),
      fill: new ol.style.Fill({ color: 'rgba(255,123,0,0.15)' }),
      image: new ol.style.Circle({ radius: 12, stroke: new ol.style.Stroke({ color: '#ff7b00', width: 3 }) }),
    }),
  }));
  map.addLayer(markerLayer);

  function refreshMarkers(items) {
    markerSource.clear();
    var byB = groupBy(items, function (it) { return it.building; });
    Object.keys(byB).forEach(function (b) {
      var p = places[b];
      if (!p || !p.c) return;
      markerSource.addFeature(new ol.Feature({
        geometry: new ol.geom.Point(ol.proj.fromLonLat(p.c)), building: b, count: sumQty(byB[b]),
      }));
    });
  }

  // ------------------------------------------------------------------ panel
  var toggleBar = document.getElementById('legend-toggle');
  var btn = document.createElement('button');
  btn.id = 'inv-btn';
  btn.title = 'Furniture & Equipment (PPE register)';
  btn.textContent = '▦ Inventory';
  if (toggleBar) toggleBar.appendChild(btn);
  else { btn.className = 'inv-floating-btn'; document.body.appendChild(btn); }

  var panel = document.createElement('aside');
  panel.id = 'inv-panel';
  panel.className = 'inv-hidden';
  panel.innerHTML =
    '<header class="inv-head"><h2>Furniture &amp; Equipment</h2>' +
    '<button class="inv-close" title="Close" aria-label="Close">×</button></header>' +
    '<div class="inv-totals"></div>' +
    '<div class="inv-filters">' +
    '<input type="search" class="inv-search" placeholder="Search item, room, building, asset code…">' +
    '<div class="inv-row"><select class="inv-cat" aria-label="Category"></select>' +
    '<select class="inv-cond" aria-label="Condition"></select></div></div>' +
    '<div class="inv-selected"></div>' +
    '<div class="inv-list"></div>' +
    '<footer class="inv-foot"><button class="inv-export">Download this view (CSV)</button>' +
    (LIVE ? '<a class="inv-admin" href="' + adminLink() + '" target="_blank">Admin ↗</a>' : '') +
    '<span class="inv-gen"></span></footer>';
  document.body.appendChild(panel);
  var $ = function (sel) { return panel.querySelector(sel); };

  function fillFilters() {
    var opt = function (v, cur) { return '<option' + (v === cur ? ' selected' : '') + '>' + esc(v) + '</option>'; };
    var cats = Object.keys(groupBy(DATA.items, function (it) { return it.category || 'Other'; })).sort();
    var conds = Object.keys(groupBy(DATA.items, function (it) { return it.condition || 'Unknown'; })).sort();
    $('.inv-cat').innerHTML = '<option value="All">All categories</option>' + cats.map(function (c) { return opt(c, state.cat); }).join('');
    $('.inv-cond').innerHTML = '<option value="All">All conditions</option>' + conds.map(function (c) { return opt(c, state.cond); }).join('');
  }

  function itemTable(items) {
    var byRoom = groupBy(items, function (it) { return it.room || 'Room not specified'; });
    return Object.keys(byRoom).sort().map(function (room) {
      var rows = byRoom[room].map(function (it) {
        var meta = [it.code, it.category, it.date ? 'Purchased ' + it.date : '', it.cost != null ? 'Nu. ' + money(it.cost) + ' each' : '']
          .filter(Boolean).map(esc).join(' · ');
        return '<tr><td><span class="inv-chip" style="background:' + catColor(it.category) + '"></span>' + esc(it.description) +
          (meta ? '<small>' + meta + '</small>' : '') +
          (it.remarks ? '<small class="inv-rem">' + esc(it.remarks) + '</small>' : '') + '</td>' +
          '<td class="inv-num">' + esc(it.qty) + '</td>' +
          '<td><span class="inv-cond-tag inv-c-' + esc(String(it.condition || '').toLowerCase().replace(/[^a-z]/g, '')) + '">' +
          esc(it.condition || '-') + '</span></td></tr>';
      }).join('');
      return '<h4>' + esc(room) + ' <span>' + sumQty(byRoom[room]) + (sumQty(byRoom[room]) === 1 ? ' item' : ' items') + '</span></h4>' +
        '<table><thead><tr><th>Asset</th><th>Qty</th><th>Condition</th></tr></thead><tbody>' + rows + '</tbody></table>';
    }).join('');
  }

  function render() {
    var items = filtered();
    refreshMarkers(items);
    $('.inv-gen').textContent = (LIVE ? 'Live from ' + SOURCE + ' · ' : 'Data from ') + new Date(DATA.generated).toLocaleString();

    var byCat = groupBy(items, function (it) { return it.category || 'Other'; });
    var cats = Object.keys(byCat).sort(function (a, b) { return sumQty(byCat[b]) - sumQty(byCat[a]); });
    $('.inv-totals').innerHTML = cats.slice(0, 3).map(function (c) {
      return '<div><b style="color:' + catColor(c) + '">' + sumQty(byCat[c]) + '</b>' + esc(c) + '</div>';
    }).join('') + '<div><b>' + Object.keys(groupBy(items, function (it) { return it.building; })).length + '</b>Buildings</div>';

    var selBox = $('.inv-selected'), list = $('.inv-list');
    if (state.selected) {
      var mine = items.filter(function (it) { return it.building === state.selected; });
      var p = places[state.selected];
      var cost = sumCost(mine);
      selBox.innerHTML = '<div class="inv-sel-card"><div class="inv-sel-title"><div><h3>' + esc(state.selected) + '</h3>' +
        '<small>' + esc(p ? p.layer : '') + ' · ' + sumQty(mine) + (sumQty(mine) === 1 ? ' item' : ' items') + (cost ? ' · Nu. ' + money(cost) : '') + '</small></div>' +
        '<button class="inv-clear" title="Show all buildings">All</button></div>' +
        (mine.length ? itemTable(mine) : '<p class="inv-empty">No assets recorded for this building' +
          (state.q || state.cat !== 'All' || state.cond !== 'All' ? ' with the current filters' : '') + '.' +
          (LIVE ? ' <a href="' + adminLink(state.selected) + '" target="_blank">Add one ↗</a>' :
            ' Add rows to the Excel sheet with Location = <code>' + esc(state.selected) + '</code>.') + '</p>') +
        '</div>';
      list.style.display = 'none';
      return;
    }
    selBox.innerHTML = '';
    list.style.display = '';
    var byB = groupBy(items, function (it) { return it.building; });
    var keys = Object.keys(byB).sort(function (a, b) { return sumQty(byB[b]) - sumQty(byB[a]); });
    list.innerHTML = keys.length ? keys.map(function (b) {
      return '<details><summary><span class="inv-bname" data-b="' + esc(b) + '">' + esc(b) + '</span>' +
        '<span class="inv-count">' + sumQty(byB[b]) + '</span></summary>' + itemTable(byB[b]) + '</details>';
    }).join('') : '<p class="inv-empty">' + (DATA.items.length ? 'No assets match these filters.' :
      'No assets recorded yet.' + (LIVE ? ' <a href="' + adminLink() + '" target="_blank">Open the admin page ↗</a>' : '')) + '</p>';
  }

  function select(key, zoom) {
    state.selected = key;
    highlightSource.clear();
    var p = places[key];
    if (p) {
      var f = fmt.readFeature({ type: 'Feature', geometry: p.g, properties: {} }, toMap);
      highlightSource.addFeature(f);
      if (zoom) map.getView().fit(f.getGeometry().getExtent(), { maxZoom: 19, padding: [80, 420, 80, 80], duration: 400 });
    }
    styleCache = {};
    openPanel();
    render();
  }
  function clearSelection() { state.selected = null; highlightSource.clear(); styleCache = {}; render(); }
  function openPanel() { panel.classList.remove('inv-hidden'); btn.classList.add('inv-active'); }
  function closePanel() { panel.classList.add('inv-hidden'); btn.classList.remove('inv-active'); }

  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (panel.classList.contains('inv-hidden')) openPanel(); else closePanel();
  });
  $('.inv-close').addEventListener('click', closePanel);
  $('.inv-search').addEventListener('input', function (e) { state.q = e.target.value.trim(); render(); });
  $('.inv-cat').addEventListener('change', function (e) { state.cat = e.target.value; render(); });
  $('.inv-cond').addEventListener('change', function (e) { state.cond = e.target.value; render(); });
  panel.addEventListener('click', function (e) {
    var b = e.target.closest('.inv-bname');
    if (b) { e.preventDefault(); select(b.getAttribute('data-b'), true); }
    if (e.target.closest('.inv-clear')) clearSelection();
  });
  $('.inv-export').addEventListener('click', function () {
    var items = filtered().filter(function (it) { return !state.selected || it.building === state.selected; });
    var head = ['Sl. No.', 'Asset Code / Tag No.', 'Asset Description', 'Category', 'Location', 'Custodian/Room',
      'Date of Purchase', 'Cost (Nu.)', 'Qty Found Physically', 'Condition', 'Remarks'];
    var cell = function (v) { v = String(v == null ? '' : v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
    var csv = '﻿' + [head].concat(items.map(function (it) {
      return [it.sl, it.code, it.description, it.category, it.building, it.room, it.date, it.cost, it.qty, it.condition, it.remarks];
    })).map(function (r) { return r.map(cell).join(','); }).join('\r\n');
    var a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    a.download = (state.selected ? state.selected.replace(/[^\w-]+/g, '_') : 'sherubtse') + '_PPE.csv';
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 1000);
  });

  // -------------------------------------------------------------- map clicks
  function pointInRing(pt, ring) {
    var inside = false;
    for (var i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      var xi = ring[i][0], yi = ring[i][1], xj = ring[j][0], yj = ring[j][1];
      if ((yi > pt[1]) !== (yj > pt[1]) && pt[0] < (xj - xi) * (pt[1] - yi) / (yj - yi) + xi) inside = !inside;
    }
    return inside;
  }
  function placeAt(lonlat) {
    for (var i = DATA.places.length - 1; i >= 0; i--) {
      var g = DATA.places[i].g;
      var polys = g.type === 'Polygon' ? [g.coordinates] : g.type === 'MultiPolygon' ? g.coordinates : [];
      for (var k = 0; k < polys.length; k++) if (pointInRing(lonlat, polys[k][0])) return DATA.places[i].key;
    }
    return null;
  }
  var hasItems = function (key) { return DATA.items.some(function (it) { return it.building === key; }); };

  map.on('singleclick', function (evt) {
    var hit = map.forEachFeatureAtPixel(evt.pixel, function (f) { return f; }, {
      layerFilter: function (l) { return l === markerLayer; }, hitTolerance: 4,
    });
    if (hit) { select(hit.get('building'), false); return; }
    var key = placeAt(ol.proj.toLonLat(evt.coordinate));
    // Open the panel by itself for buildings that have assets; when the panel
    // is already open, show any building clicked.
    if (key && (hasItems(key) || !panel.classList.contains('inv-hidden'))) select(key, false);
  });
  map.on('pointermove', function (evt) {
    if (!evt.dragging && map.hasFeatureAtPixel(evt.pixel, { layerFilter: function (l) { return l === markerLayer; } })) {
      map.getViewport().style.cursor = 'pointer';
    }
  });

  // ------------------------------------------------------------- live data
  function loadAssets() {
    if (GAS) {
      return new Promise(function (resolve, reject) {
        google.script.run.withSuccessHandler(function (assets) { resolve({ assets: assets }); })
          .withFailureHandler(reject).getAssets();
      });
    }
    return fetch('/api/assets', { cache: 'no-store' }).then(function (r) { return r.ok ? r.json() : null; });
  }
  function refreshLive() {
    if (!LIVE) return;
    loadAssets().then(function (j) {
      if (!j) return;
      var next = j.assets.filter(function (a) { return a.building; });
      if (JSON.stringify(next) === JSON.stringify(DATA.items)) return;
      DATA.items = next;
      DATA.generated = new Date().toISOString();
      styleCache = {};
      fillFilters();
      render();
    }).catch(function () { /* server offline: keep last data */ });
  }

  fillFilters();
  render();
  // Apps Script pages run in an iframe, so ?building= is passed in by the template.
  var startB = window.PPE_START_BUILDING || new URLSearchParams(location.search).get('building');
  if (startB && places[startB]) setTimeout(function () { select(startB, true); }, 300);
  if (LIVE) {
    refreshLive();
    setInterval(refreshLive, GAS ? 60000 : 15000); // gentler on Apps Script quotas
    window.addEventListener('focus', refreshLive);
  }
})();
